import{_ as e}from"./chunks/caa2-icon.BEF7h3oD.js";import{_ as i,o as t,c as s,a2 as r}from"./chunks/framework.Crpw6aS5.js";const o="/assets/01-chat.34oVSODw.png",n="/assets/02-docs._hdpprQu.png",m=JSON.parse('{"title":"SACAA Air Law Assistant (CAA2.0)","description":"CAA2.0 — SACAA air-law Q&A assistant with cited regs, AIP, AICs, and forms.","frontmatter":{"title":"SACAA Air Law Assistant (CAA2.0)","description":"CAA2.0 — SACAA air-law Q&A assistant with cited regs, AIP, AICs, and forms."},"headers":[],"relativePath":"software-engineering/android-app-development/caa2-sacaa-air-law-assistant.md","filePath":"software-engineering/android-app-development/caa2-sacaa-air-law-assistant.md"}'),l={name:"software-engineering/android-app-development/caa2-sacaa-air-law-assistant.md"};function c(d,a,p,A,u,h){return t(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="sacaa-air-law-assistant-caa2-0" tabindex="-1">SACAA Air Law Assistant (CAA2.0) <a class="header-anchor" href="#sacaa-air-law-assistant-caa2-0" aria-label="Permalink to &quot;SACAA Air Law Assistant (CAA2.0)&quot;">​</a></h1><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: text + project store listing</li><li>Origin: user provided (project <code>caa2.0</code>); store kit at <code>caa2.0/store/play/LISTING.md</code></li><li>Web: <a href="https://sacaa.app" target="_blank" rel="noreferrer">https://sacaa.app</a> · Package: <code>com.devsdev.easyaip</code></li><li>Imported: 2026-07-31</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><img src="'+e+'" alt="SACAA Air Law Assistant icon"></p><p><strong>Codename:</strong> CAA2.0 · <strong>Public name:</strong> SACAA Air Law Assistant · <strong>Category:</strong> Education · <strong>Package:</strong> <code>com.devsdev.easyaip</code></p><p>Ask SACAA air-law questions with cited regs, AIP, AICs &amp; forms.</p><p>SACAA Air Law Assistant helps South African student pilots, licensed pilots, and aviation professionals find answers in civil aviation regulations — with citations you can open and verify.</p><blockquote><p>This app is an unofficial study and reference assistant. It is not affiliated with, endorsed by, or operated by the South African Civil Aviation Authority (SACAA). Always verify answers against the official SACAA / LexisNexis publications before making flight, licensing, or operational decisions.</p></blockquote><h3 id="what-you-can-ask" tabindex="-1">What you can ask <a class="header-anchor" href="#what-you-can-ask" aria-label="Permalink to &quot;What you can ask&quot;">​</a></h3><ul><li>Private pilot licence requirements, medicals, and renewals</li><li>Forms and personal particulars updates (contact details with SACAA)</li><li>Airspace questions (CTR, TMA) grounded in published definitions</li><li>AIP, AIC, and CATS references for day-to-day operations</li><li>Instructor ratings and related Part 61 topics</li></ul><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li>Sign in and ask in plain language</li><li>The assistant retrieves relevant SACAA documents from a curated corpus</li><li>Answers stream with source citations — tap a source to open the PDF at the cited page</li></ol><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Conversational Q&amp;A with saved chat history</li><li>Document browser for the indexed corpus</li><li>In-app PDF viewer with page highlighting</li><li>Progressive Web App support — also available on the web</li><li>Works offline for previously loaded UI assets (answers require connectivity)</li></ul><h3 id="distribution-status" tabindex="-1">Distribution status <a class="header-anchor" href="#distribution-status" aria-label="Permalink to &quot;Distribution status&quot;">​</a></h3><ul><li><strong>Web / PWA:</strong> <a href="https://sacaa.app" target="_blank" rel="noreferrer">https://sacaa.app</a> (privacy policy at <code>/privacy</code>)</li><li><strong>Google Play:</strong> packaging kit ready (<code>com.devsdev.easyaip</code>); listing not live on Play at import time (404 for package ID)</li></ul><h3 id="privacy-summary" tabindex="-1">Privacy (summary) <a class="header-anchor" href="#privacy-summary" aria-label="Permalink to &quot;Privacy (summary)&quot;">​</a></h3><p>Account credentials secure conversations. Chat queries are used for app functionality. See the in-app / hosted privacy policy for details.</p><h3 id="figures" tabindex="-1">Figures <a class="header-anchor" href="#figures" aria-label="Permalink to &quot;Figures&quot;">​</a></h3><p><img src="'+o+'" alt="Chat with cited Form CA 183-501 answer"></p><p><img src="'+n+'" alt="Documents browser"></p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li><strong>CAA2.0</strong> ships as <strong>SACAA Air Law Assistant</strong> — RAG Q&amp;A over SACAA regs/AIP/forms with openable PDF citations.</li><li>Public surface: <a href="https://sacaa.app" target="_blank" rel="noreferrer">sacaa.app</a>; Android package <code>com.devsdev.easyaip</code> prepared for Play.</li><li>Unofficial study aid — not affiliated with SACAA; always verify against official publications.</li></ul>',24)])])}const w=i(l,[["render",c]]);export{m as __pageData,w as default};
